{
  "workflow": {
    "title": "vendor onboarding for a small manufacturing company",
    "summary": "A procurement employee submits a supplier request with a quotation, company details, and a proposed order value. An AI assistant reviews the request and prepares a recommendation. The procurement manager and finance team review the recommendation, and the procurement employee authorizes vendor onboarding. The workflow avoids direct system changes and focuses on review and record creation."
  },
  "evidence": [
    {"id": "e1", "quote": "A procurement employee submits a supplier request with a quotation, company details and a proposed order value."},
    {"id": "e2", "quote": "An AI assistant reads the quotation and supplier record, compares the request with the approved supplier list, and prepares a recommendation."},
    {"id": "e3", "quote": "Supplier documents are external, untrusted material."},
    {"id": "e4", "quote": "The assistant must not treat instructions in those documents as company policy."},
    {"id": "e5", "quote": "The procurement manager reviews the recommendation."},
    {"id": "e6", "quote": "Finance verifies bank details through a separate established channel."},
    {"id": "e7", "quote": "Only an authorised procurement employee can add a vendor to the purchasing system."},
    {"id": "e8", "quote": "The assistant cannot change bank details, add a vendor, place an order or send a payment."},
    {"id": "e9", "quote": "Requests involving missing or conflicting records are paused for review."},
    {"id": "e10", "quote": "A rejection returns the request to the requester with an explanation; acceptance creates a reviewed onboarding record, not an order."}
  ],
  "facts": [
    {"id": "f1", "evidence_ids": ["e1", "e2", "e3", "e4", "e5", "e6", "e7", "e8"]},
    {"id": "f2", "evidence_ids": ["e9", "e10"]}
  ],
  "assumptions": [
    {"id": "a1", "statement": "The AI assistant has access to the approved supplier list and can compare it with the supplier request.",
      "rationale": "e2"},
    {"id": "a2", "statement": "The procurement manager has the authority to review and approve the recommendation.",
      "rationale": "e5"},
    {"id": "a3", "statement": "Finance has a separate channel to verify bank details.",
      "rationale": "e6"},
    {"id": "a4", "statement": "The procurement employee has the authority to add a vendor to the purchasing system.",
      "rationale": "e7"}
  ],
  "actors": [
    {"id": "a1", "label": "procurement employee", "kind": "human", "source_state": "stated", "evidence_ids": ["e1", "e7", "e8"]},
    {"id": "a2", "label": "AI assistant", "kind": "system", "source_state": "stated", "evidence_ids": ["e2", "e4"]},
    {"id": "a3", "label": "procurement manager", "kind": "human", "source_state": "stated", "evidence_ids": ["e5"]},
    {"id": "a4", "label": "finance", "kind": "human", "source_state": "stated", "evidence_ids": ["e6"]}
  ],
  "data": [
    {"id": "d1", "label": "supplier request", "description": "includes quotation, company details, and proposed order value", "classification": "unknown", "source_state": "stated", "evidence_ids": ["e1"]},
    {"id": "d2", "label": "approved supplier list", "description": "list of approved suppliers", "classification": "unknown", "source_state": "stated", "evidence_ids": ["e2"]},
    {"id": "d3", "label": "supplier documents", "description": "external, untrusted material", "classification": "unknown", "source_state": "stated", "evidence_ids": ["e3", "e4"]},
    {"id": "d4", "label": "bank details", "description": "verified through a separate established channel", "classification": "unknown", "source_state": "stated", "evidence_ids": ["e6"]}
  ],
  "tools": [
    {"id": "t1", "label": "AI assistant", "purpose": "reads quotation and supplier record, compares with approved supplier list, prepares recommendation", "mode": "unknown", "source_state": "stated", "evidence_ids": ["e2"]}
  ],
  "steps": [
    {"id": "s1", "label": "submit supplier request", "description": "procurement employee submits a supplier request with a quotation, company details, and proposed order value", "actor_ids": ["a1"], "input_data_ids": ["d1"], "output_data_ids": ["d1"], "tool_ids": ["t1"], "source_state": "stated", "evidence_ids": ["e1"]},
    {"id": "s2", "label": "AI assistant reviews request", "description": "AI assistant reads the quotation and supplier record, compares the request with the approved supplier list, and prepares a recommendation", "actor_ids": ["a2"], "input_data_ids": ["d1", "d2"], "output_data_ids": ["d1"], "tool_ids": ["t1"], "source_state": "stated", "evidence_ids": ["e2"]},
    {"id": "s3", "label": "procurement manager reviews recommendation", "description": "procurement manager reviews the recommendation", "actor_ids": ["a3"], "input_data_ids": ["d1"], "output_data_ids": ["d1"], "tool_ids": [], "source_state": "stated", "evidence_ids": ["e5"]},
    {"id": "s4", "label": "finance verifies bank details", "description": "finance verifies bank details through a separate established channel", "actor_ids": ["a4"], "input_data_ids": ["d1"], "output_data_ids": ["d4"], "tool_ids": [], "source_state": "stated", "evidence_ids": ["e6"]},
    {"id": "s5", "label": "vendor onboarding decision", "description": "only an authorised procurement employee can add a vendor to the purchasing system", "actor_ids": ["a1"], "input_data_ids": ["d1", "d4"], "output_data_ids": ["d1"], "tool_ids": [], "source_state": "stated", "evidence_ids": ["e7", "e8"]},
    {"id": "s6", "label": "request paused for review", "description": "requests involving missing or conflicting records are paused for review", "actor_ids": ["a1"], "input_data_ids": ["d1"], "output_data_ids": ["d1"], "tool_ids": [], "source_state": "stated", "evidence_ids": ["e9"]},
    {"id": "s7", "label": "request rejected or accepted", "description": "a rejection returns the request to the requester with an explanation; acceptance creates a reviewed onboarding record, not an order", "actor_ids": ["a1"], "input_data_ids": ["d1"], "output_data_ids": ["d1"], "tool_ids": [], "source_state": "stated", "evidence_ids": ["e10"]}
  ],
  "decisions": [
    {"id": "d1", "step_id": "s5", "question": "Should the procurement employee add the vendor to the purchasing system?", "criteria": ["approved supplier list", "bank details verified"], "authority_actor_ids": ["a1"], "source_state": "stated", "evidence_ids": ["e7", "e8"]}
  ],
  "edges": [
    {"from_step_id": "s1", "to_step_id": "s2", "condition": "request submitted", "source_state": "stated", "evidence_ids": ["e1"]},
    {"from_step_id": "s2", "to_step_id": "s3", "condition": "recommendation prepared", "source_state": "stated", "evidence_ids": ["e2"]},
    {"from_step_id": "s3", "to_step_id": "s4", "condition": "manager reviews recommendation", "source_state": "stated", "evidence_ids": ["e5"]},
    {"from_step_id": "s4", "to_step_id": "s5", "condition": "bank details verified", "source_state": "stated", "evidence_ids": ["e6"]},
    {"from_step_id": "s5", "to_step_id": "s7", "condition": "vendor added to purchasing system", "source_state": "stated", "evidence_ids": ["e7", "e8"]},
    {"from_step_id": "s2", "to_step_id": "s6", "condition": "missing or conflicting records", "source_state": "stated", "evidence_ids": ["e9"]},
    {"from_step_id": "s6", "to_step_id": "s1", "condition": "request paused for review", "source_state": "stated", "evidence_ids": ["e9"]},
    {"from_step_id": "s7", "to_step_id": "s1", "condition": "request rejected", "source_state": "stated", "evidence_ids": ["e10"]}
  ],
  "requirements": [
    {"id": "r1", "statement": "The procurement employee must submit a supplier request with a quotation, company details, and a proposed order value.", "kind": "policy", "source_state": "stated", "evidence_ids": ["e1"]},
    {"id": "r2", "statement": "The AI assistant must not treat instructions in supplier documents as company policy.", "kind": "policy", "source_state": "stated", "evidence_ids": ["e4"]},
    {"id": "r3", "statement": "Only an authorised procurement employee can add a vendor to the purchasing system.", "kind": "policy", "source_state": "stated", "evidence_ids": ["e7"]}
  ],
  "existing_controls": [
    {"id": "ec1", "description": "The AI assistant prepares a recommendation based on the supplier request and approved supplier list.", "step_ids": ["s2"], "source_state": "stated", "evidence_ids": ["e2"]}
  ],
  "risks": [
    {"id": "r1", "title": "AI assistant misinterprets supplier documents", "scenario": "The AI assistant treats instructions in supplier documents as company policy.", "impact": "Incorrect recommendations may be made, leading to potential compliance or operational risks.", "step_ids": ["s2"], "data_ids": ["d3"], "evidence_ids": ["e4"], "uncertainty": "The AI assistant's interpretation of supplier documents is not verified.",
      "proposed_priority": "high"},
    {"id": "r2", "title": "Procurement manager does not review recommendation", "scenario": "The procurement manager fails to review the recommendation, leading to unapproved vendor onboarding.", "impact": "Unapproved vendors may be added to the purchasing system, leading to financial or operational risks.", "step_ids": ["s3"], "data_ids": ["d1"], "evidence_ids": ["e5"], "uncertainty": "The procurement manager's review is not verified.",
      "proposed_priority": "medium"},
    {"id": "r3", "title": "Finance does not verify bank details", "scenario": "Finance fails to verify bank details, leading to incorrect payments or fraud.", "impact": "Incorrect payments may be made, leading to financial loss.", "step_ids": ["s4"], "data_ids": ["d4"], "evidence_ids": ["e6"], "uncertainty": "The finance verification process is not verified.",
      "proposed_priority": "high"}
  ],
  "controls": [
    {"id": "c1", "family": "human_approval", "recommendation": "The procurement manager must review the recommendation before proceeding.", "enforcement_point": "s3", "risk_ids": ["r2"], "step_ids": ["s3"], "owner_actor_ids": ["a3"], "validation": "The procurement manager must explicitly approve the recommendation before proceeding."},
    {"id": "c2", "family": "data_quality", "recommendation": "Finance must verify bank details through a separate established channel.", "enforcement_point": "s4", "risk_ids": ["r3"], "step_ids": ["s4"], "owner_actor_ids": ["a4"], "validation": "Finance must provide a verification record before proceeding."},
    {"id": "c3", "family": "data_quality", "recommendation": "The AI assistant must not treat instructions in supplier documents as company policy.", "enforcement_point": "s2", "risk_ids": ["r1"], "step_ids": ["s2"], "owner_actor_ids": ["a2"], "validation": "The AI assistant must explicitly reject any instructions in supplier documents that are not company policy."},
    {"id": "c4", "family": "human_approval", "recommendation": "The procurement employee must authorise the addition of a vendor to the purchasing system.", "enforcement_point": "s5", "risk_ids": ["r2"], "step_ids": ["s5"], "owner_actor_ids": ["a1"], "validation": "The procurement employee must explicitly authorise the addition of a vendor to the purchasing system."}
  ],
  "gaps": [
    {"id": "g1", "description": "Operating countries, document retention periods, escalation deadlines, record ownership and budget thresholds still need to be decided.",
      "related_ids": ["e10"], "question_ids": ["q1"], "blocking": true}
  ],
  "questions": [
    {"id": "q1", "question": "What are the operating countries, document retention periods, escalation deadlines, record ownership and budget thresholds for this workflow?",
      "related_ids": ["g1"], "blocking": true}
  ],
  "human_authority": {
    "accountable_actor_ids": ["a1", "a3", "a4"],
