      {"step_id": "s5", "recommended_actor_ids": ["a1"], "reason": "The procurement employee must authorise the addition of a vendor to the purchasing system.",
        "control_ids": ["c4"]}
    ],
    "escalation": "If the procurement manager does not review the recommendation, the request should be escalated to a higher authority for review."
  }
